// ===== data (generated by build_data.py from GolfCourseMCE.gpkg, OD matrix and towns) =====
const COURSES = DATA.courses, TOWNS = DATA.towns, MIN = DATA.minutes;
const TIDX = Object.fromEntries(TOWNS.map((t,i)=>[t.name,i]));
// Public transport estimate: drive time x 1.5, plus a waiting allowance by service level.
// Courses with no service ('None') are treated as not reachable by public transport.
const PT_FACTOR = 1.5, PT_WAIT = {Excellent:10, Good:20, Limited:40};

function travel(ti, ci, mode){
  const d = MIN[ti][ci];
  if (d == null) return null;
  if (mode === 'pt'){ const w = PT_WAIT[COURSES[ci].ptClass]; return w == null ? null : Math.round(d*PT_FACTOR + w); }
  return d;
}

// ---------- scoring ----------
const W = {important:2, somewhat:1, skip:0};
function findCourses(a){
  const ti = TIDX[a.town];
  const out = [];
  COURSES.forEach((c,ci)=>{
    const t = travel(ti, ci, a.mode);
    if (t == null || t > a.maxTime) return;
    if (a.type !== 'any' && c.type !== a.type) return;
    if (a.rank === 'top100' && !c.top100) return;
    if (a.size !== 'any' && c.size.toLowerCase() !== a.size) return;
    const parts = [
      {k: a.mode==='pt' ? 'Journey time' : 'Drive time', w:1, s:Math.max(0, 1 - t/a.maxTime)},
      {k:'Quietness', w:W[a.quiet], s:c.quiet},
      {k:'Environment', w:W[a.env], s:c.env},
    ];
    if (a.mode==='pt') parts.push({k:'Service level', w:1, s:c.pt});
    const used = parts.filter(p => p.w > 0 && p.s != null);
    const tw = used.reduce((x,p)=>x+p.w,0);
    out.push({c, ci, mins:t, parts:used, score: used.reduce((x,p)=>x+p.w*p.s,0)/tw*100});
  });
  return out.sort((x,y)=>y.score-x.score || x.mins-y.mins);
}

// ---------- wizard ----------
const A = {mode:null, town:"Athlone", maxTime:90, type:"any", size:"any", rank:"any", quiet:"skip", env:"skip"};
let step = 0, results = [], active = 0;
const STEPS = ['mode','start','type','size','rank','quiet','env','results'];
const stepLabel = () => `Step ${step+1} of ${STEPS.length-1}`;
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"]/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
const cap = s => s.charAt(0).toUpperCase()+s.slice(1);
function fmt(m){ return m<60?`${m} min`:`${Math.floor(m/60)} h${m%60?` ${m%60} min`:''}`; }

function optList(key, items){
  return `<div class="opts">${items.map(([v,l,s])=>`
    <button class="opt ${A[key]===v?'sel':''}" data-k="${key}" data-v="${v}">
      <span class="dot"></span><span>${l}${s?`<small>${s}</small>`:''}</span></button>`).join('')}</div>`;
}
// Does a course pass every answer given so far? (unanswered = "any", so it doesn't filter)
function matches(ci){
  const c=COURSES[ci];
  if (A.mode && STEPS[step]!=='mode'){ const t=travel(TIDX[A.town],ci,A.mode); if (t==null || t>A.maxTime) return false; }
  if (A.type!=='any' && c.type!==A.type) return false;
  if (A.size!=='any' && c.size.toLowerCase()!==A.size) return false;
  if (A.rank==='top100' && !c.top100) return false;
  return true;
}
function liveCount(){
  const el=$('#live'); if(!el) return;
  const s=STEPS[step];
  if (s==='results'){ el.style.display='none'; return; }
  el.style.display='';
  let n=0; COURSES.forEach((c,ci)=>{ if(matches(ci)) n++; });
  const note = (s==='quiet'||s==='env') ? ' · this question changes the ranking, not the number' : '';
  el.innerHTML=`<b>${n}</b> of ${COURSES.length} courses match so far${note}`;
  el.classList.toggle('zero', n===0);
}
function countIn(){ // live count of courses in range on the start step
  const ti=TIDX[A.town]; let n=0; COURSES.forEach((c,ci)=>{const t=travel(ti,ci,A.mode); if(t!=null&&t<=A.maxTime) n++;}); return n;
}

function render(){
  $('#progress').innerHTML = STEPS.map((s,i)=>`<span class="${i<step?'done':i===step?'now':''}"></span>`).join('');
  const b = $('#body'), f = $('#footer'), s = STEPS[step];
  const nav = (skippable) => `
    ${step>0?'<button class="btn" id="back">Back</button>':''}<span class="grow"></span>
    ${skippable?'<button class="btn link" id="skip">Skip</button>':''}
    <button class="btn primary" id="next" ${s==='mode'&&!A.mode?'disabled style="opacity:.45;cursor:not-allowed"':''}>${s==='env'?'Find my course':'Next'}</button>`;
  const pt = A.mode==='pt';

  if (s==='mode'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>How will you get there?</h2>
      <p class="hint">We'll work out travel times from your town to every course.</p>
      ${optList('mode',[['drive','Drive','Road drive times from your town'],['pt','Public transport','Only courses with a bus or rail service nearby, with an estimated journey time']])}`;
    f.innerHTML = nav(false);
  }
  if (s==='start'){
    const sorted = TOWNS.map(t=>t.name).sort((x,y)=>x.localeCompare(y));
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>Where are you starting from?</h2>
      <p class="hint">${pt?'Journey time is estimated as drive time × 1.5 plus waiting time (10 min for excellent service, 20 min good, 40 min limited).':'Drive times are calculated on the road network from your town to each course.'}</p>
      <label class="f" for="town">Starting town</label>
      <select id="town">${sorted.map(n=>`<option ${n===A.town?'selected':''}>${esc(n)}</option>`).join('')}</select>
      <label class="f" for="md">Maximum ${pt?'journey':'drive'} time</label>
      <div class="rangeval" id="mdv">${fmt(A.maxTime)}</div>
      <input type="range" id="md" min="15" max="300" step="15" value="${A.maxTime}">`;
    f.innerHTML = nav(false);
    const upd=()=>{ liveCount(); drawMap(); };
    $('#town').onchange = e => {A.town = e.target.value; upd();};
    $('#md').oninput = e => {A.maxTime = +e.target.value; $('#mdv').textContent = fmt(A.maxTime); upd();};
  }
  if (s==='type'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>What kind of course?</h2>
      <p class="hint">Only courses of this type will be shown.</p>
      ${optList('type',[['links','Links','Coastal, sandy, windswept'],['parkland','Parkland','Inland, tree-lined'],['heathland','Heathland','Open heather and gorse'],['upland','Upland','Hilly, elevated courses'],['any',"Don't mind",'']])}`;
    f.innerHTML = nav(true);
  }
  if (s==='size'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>What size of course?</h2>
      <p class="hint">Based on the area of the course.</p>
      ${optList('size',[['small','Small','Under about 40 hectares'],['medium','Medium','About 40–58 hectares'],['large','Large','Over about 56 hectares, up to 217'],['any',"Don't mind",'']])}`;
    f.innerHTML = nav(true);
  }
  if (s==='rank'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>Only top-100 courses?</h2>
      <p class="hint">Based on a published list of Ireland's top 100 golf courses.</p>
      ${optList('rank',[['top100','Top 100 only','79 courses'],['any',"Don't mind",'Include every course']])}`;
    f.innerHTML = nav(true);
  }
  if (s==='quiet'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>Do you want a quieter course?</h2>
      <p class="hint">Based on how many people live within 30 minutes compared with how many courses they share.</p>
      ${optList('quiet',[['important','Very important',''],['somewhat','Somewhat',''],['skip','Not bothered','']])}`;
    f.innerHTML = nav(true);
  }
  if (s==='env'){
    b.innerHTML = `<div class="step-k">${stepLabel()}</div><h2>Natural surroundings?</h2>
      <p class="hint">Land cover and overlap with Special Areas of Conservation and Special Protection Areas.</p>
      ${optList('env',[['important','Very important',''],['somewhat','Somewhat',''],['skip','Not bothered','']])}`;
    f.innerHTML = nav(true);
  }
  if (s==='results'){
    results = findCourses(A); active = 0;
    const bits=[pt?'by public transport':'driving', `from <b>${esc(A.town)}</b>`, `up to ${fmt(A.maxTime)}`,
      A.type==='any'?'any type':A.type, A.size==='any'?null:A.size, A.rank==='top100'?'top 100':null, A.quiet!=='skip'?'quieter':null, A.env!=='skip'?'natural':null].filter(Boolean);
    let html = `<div class="step-k">Your matches</div><h2>${results.length?'Best courses for you':'No exact matches'}</h2>
      <div class="summary">${cap(bits.join(' · '))}<br><span style="color:var(--muted)">${results.length} course${results.length===1?'':'s'} passed your filters.</span></div>`;
    html += results.length ? results.slice(0,3).map((r,i)=>card(r,i)).join('') + compare(results.slice(0,3)) : `<div class="empty">Nothing matches all of those. ${suggest()}</div>`;
    b.innerHTML = html;
    f.innerHTML = `<button class="btn" id="back">Back</button><span class="grow"></span><button class="btn primary" id="restart">Start over</button>`;
    b.querySelectorAll('.card').forEach(el=>el.onclick = e => { if (e.target.closest('details')) return; active=+el.dataset.i; highlight(); drawMap(); });
    b.querySelectorAll('[data-relax]').forEach(el=>el.onclick=()=>{ const [k,v]=el.dataset.relax.split(':'); A[k]= k==='maxTime'?+v:v; render(); });
  }

  b.querySelectorAll('.opt').forEach(el=>el.onclick=()=>{
    const k=el.dataset.k, v=el.dataset.v;
    if (k==='mode' && A.mode!==v) A.maxTime = v==='pt'?150:90;
    A[k]=v; render();
  });
  const bk=$('#back'), nx=$('#next'), sk=$('#skip'), rs=$('#restart');
  if (bk) bk.onclick=()=>{step--; render();};
  if (nx) nx.onclick=()=>{ if (s==='mode'&&!A.mode) return; step++; render(); };
  if (sk) sk.onclick=()=>{ A[s] = (s==='type'||s==='rank'||s==='size')?'any':'skip'; step++; render(); };
  if (rs) rs.onclick=()=>{ Object.assign(A,{mode:null,type:'any',size:'any',rank:'any',quiet:'skip',env:'skip'}); step=0; render(); };
  liveCount();
  drawMap();
}

function suggest(){
  const o=[];
  if (A.maxTime<300) o.push(`<button class="btn" data-relax="maxTime:${Math.min(300,A.maxTime+60)}">Allow up to ${fmt(Math.min(300,A.maxTime+60))}</button>`);
  if (A.rank!=='any') o.push(`<button class="btn" data-relax="rank:any">Include unranked courses</button>`);
  if (A.size!=='any') o.push(`<button class="btn" data-relax="size:any">Any size</button>`);
  if (A.type!=='any') o.push(`<button class="btn" data-relax="type:any">Any course type</button>`);
  return o.length?`Try relaxing one:<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">${o.join('')}</div>`:'Try going back and changing an answer.';
}

const num = n => n==null ? '–' : n.toLocaleString('en-IE');
const pct = v => v==null ? '–' : Math.round(v*100);
function stats(c, r){
  const pt = A.mode==='pt';
  return `<div class="stats">
    <div><b>${c.area} ha</b><span>${c.size} course</span></div>
    <div><b>${c.coast_km==null?'–':c.coast_km<1?'<1 km':c.coast_km+' km'}</b><span>to the coast</span></div>
    <div><b>${num(c.elev)} m</b><span>average elevation</span></div>
    <div><b>${c.slope==null?'–':c.slope+'°'}</b><span>average slope</span></div>
    <div><b>${num(c.pop30)}</b><span>people within 30 min</span></div>
    <div><b>${num(c.n30)}</b><span>courses within 30 min</span></div>
  </div>`;
}
function profile(c){
  const row=(k,v)=>`<tr><td>${k}</td><td>${v}</td></tr>`;
  return `<details><summary>Full course profile</summary><table>
    ${row('County', esc(c.county))}
    ${row('Nearest town', `${esc(c.town)}, ${num(c.town_km)} km`)}
    ${row('Main land cover', esc(c.cover||'–'))}
    ${row('Steepest slope', c.slope_max==null?'–':c.slope_max+'°')}
    ${row('People within 15 / 30 / 60 min', `${num(c.pop15)} / ${num(c.pop30)} / ${num(c.pop60)}`)}
    ${row('Courses within 15 / 30 / 60 min', `${num(c.n15)} / ${num(c.n30)} / ${num(c.n60)}`)}
    ${row('People per course (30 min)', num(c.demand30))}
    ${row('In SAC', c.sac?`Yes, ${c.sac_pct}% of course`:'No')}
    ${row('In SPA', c.spa?`Yes, ${c.spa_pct}% of course`:'No')}
    ${row('Public transport service', esc(c.ptClass))}
    ${row('Accessibility score', pct(c.access))}
    ${row('Quietness score', pct(c.quiet))}
    ${row('Environment score', pct(c.env))}
    ${row('MCE: balanced / convenience / no car', `${pct(c.mce_bal)} / ${pct(c.mce_conv)} / ${pct(c.mce_nocar)}`)}
  </table></details>`;
}
function compare(rs){
  if (rs.length<2) return '';
  const pt=A.mode==='pt';
  const rows=[
    ['Match score', r=>Math.round(r.score)],
    [pt?'Journey time':'Drive time', r=>fmt(r.mins)],
    ['Type', r=>cap(r.c.type)],
    ['Size', r=>`${r.c.area} ha`],
    ['Top 100', r=>r.c.top100?'Yes':'No'],
    ['To coast', r=>r.c.coast_km==null?'–':r.c.coast_km<1?'<1 km':r.c.coast_km+' km'],
    ['Elevation', r=>`${num(r.c.elev)} m`],
    ['People / course', r=>num(r.c.demand30)],
    ['Quietness', r=>pct(r.c.quiet)],
    ['Environment', r=>pct(r.c.env)],
    ['PT service', r=>esc(r.c.ptClass)],
    ['MCE balanced', r=>pct(r.c.mce_bal)],
  ];
  return `<h3 class="cmp-h">Compare your top ${rs.length}</h3><table class="cmp">
    <tr><th></th>${rs.map((r,i)=>`<th><span class="badge sm">${i+1}</span></th>`).join('')}</tr>
    ${rows.map(([k,f])=>`<tr><td>${k}</td>${rs.map(r=>`<td>${f(r)}</td>`).join('')}</tr>`).join('')}
  </table><p class="hint" style="margin-top:6px">Scores are 0–100, higher is better. Hover a course on the map for its name.</p>`;
}
function card(r,i){
  const c=r.c, pt=A.mode==='pt';
  const tags=[cap(c.type), c.top100?'Top 100':null, pt?`${c.ptClass} PT service`:null, c.county, c.cover].filter(Boolean);
  const why=[pt?`about ${fmt(r.mins)} by public transport from ${esc(A.town)}`:`${fmt(r.mins)} drive from ${esc(A.town)}`];
  if (A.size!=='any') why.push(`${c.size.toLowerCase()} course (${c.area} ha)`);
  if (A.rank==='top100') why.push('one of Ireland\'s top 100');
  if (A.quiet!=='skip' && c.quiet!=null) why.push(c.quiet>.66?'quiet, low-demand area':c.quiet>.33?'moderate local demand':'busy area, but best on other criteria');
  if (A.env!=='skip'){ const p=[c.sac?'a Special Area of Conservation':null,c.spa?'a Special Protection Area':null].filter(Boolean);
    why.push(p.length?`overlaps ${p.join(' and ')}`:c.env>.5?'strong natural setting':'limited natural features'); }
  return `<div class="card ${i===0?'best':''} ${i===active?'active':''}" data-i="${i}">
    <div class="top"><span class="badge">${i+1}</span><h3>${esc(c.name)}</h3><span class="score">${Math.round(r.score)}<small>/100</small></span></div>
    <div class="bar"><i style="width:${r.score}%"></i></div>
    <div class="tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>
    <p class="why">${i===0?'<b>Best match:</b> ':''}${cap(why.join(', '))}.</p>
    ${stats(c,r)}
    ${profile(c)}
    <details><summary>How this was scored</summary><table>
      ${r.parts.map(p=>`<tr><td>${p.k} <span style="opacity:.7">(weight ${p.w})</span></td><td>${Math.round(p.s*100)}</td></tr>`).join('')}
      <tr><td><b>Weighted average</b></td><td><b>${Math.round(r.score)}</b></td></tr></table></details>
  </div>`;
}
function highlight(){ document.querySelectorAll('.card').forEach(el=>el.classList.toggle('active', +el.dataset.i===active)); }

// ---------- map (schematic outline; real coordinates for courses and towns) ----------
const OUTLINE = [[-7.37,55.38],[-7.0,55.25],[-6.95,55.17],[-6.65,55.2],[-6.15,55.22],[-5.98,55.03],[-5.8,54.85],[-5.9,54.65],[-5.45,54.5],[-5.55,54.3],[-5.66,54.22],[-5.88,54.2],[-6.1,54.03],[-6.35,53.98],[-6.22,53.8],[-6.25,53.72],[-6.1,53.58],[-6.05,53.38],[-6.2,53.33],[-6.1,53.27],[-5.99,52.96],[-6.13,52.8],[-6.2,52.56],[-6.35,52.25],[-6.36,52.17],[-6.93,52.12],[-7.15,52.15],[-7.6,52.08],[-7.85,51.95],[-8.25,51.8],[-8.53,51.6],[-8.95,51.53],[-9.4,51.5],[-9.82,51.45],[-9.6,51.6],[-10.15,51.6],[-9.75,51.78],[-10.4,51.85],[-9.9,52.05],[-10.48,52.1],[-10.2,52.27],[-9.8,52.27],[-9.95,52.42],[-9.6,52.58],[-9.93,52.56],[-9.65,52.68],[-9.35,52.93],[-9.27,53.15],[-9.05,53.27],[-9.3,53.24],[-9.9,53.35],[-10.2,53.4],[-10.05,53.5],[-9.85,53.62],[-10.2,53.95],[-10.05,54.2],[-9.98,54.3],[-9.35,54.33],[-9.2,54.22],[-8.6,54.3],[-8.45,54.47],[-8.2,54.6],[-8.75,54.62],[-8.8,54.72],[-8.45,54.9],[-8.3,55.13],[-7.98,55.2],[-7.63,55.27],[-7.37,55.38]];
const LON0=-10.7, LON1=-5.3, LAT0=51.35, LAT1=55.5, K=Math.cos(53.4*Math.PI/180), VBW=600, VBH=720, PAD=20;
const S=Math.min((VBW-2*PAD)/((LON1-LON0)*K),(VBH-2*PAD)/(LAT1-LAT0));
const offX=(VBW-(LON1-LON0)*K*S)/2, offY=(VBH-(LAT1-LAT0)*S)/2;
const P=(lon,lat)=>[offX+(lon-LON0)*K*S, offY+(LAT1-lat)*S];
// Ireland outline from Ireland_Boundary.shp (26 counties, simplified to 150 m, holes removed)
let IRL_PATH=null;
function irlPath(){
  if (IRL_PATH) return IRL_PATH;
  IRL_PATH = (typeof IRELAND!=='undefined' ? IRELAND : [OUTLINE]).map(r=>'M'+r.map(p=>P(p[0],p[1]).map(n=>n.toFixed(1)).join(',')).join('L')+'Z').join('');
  return IRL_PATH;
}
const COL={links:'#2f7d9a',parkland:'#3f8f4f',heathland:'#a0742f',upland:'#7b6aa8'};

function drawMap(){
  const svg=$('#map'), s=STEPS[step], ti=TIDX[A.town], t=TOWNS[ti];
  const showTown = A.mode && s!=='mode';
  const top = s==='results'?results.slice(0,3):[], topIds=new Set(top.map(r=>r.ci));
  const pass = new Set(s==='results'?results.map(r=>r.ci):[]);
  // zoom to the starting town + top 3 on the results step
  let vb=[0,0,VBW,VBH];
  if (top.length){
    const xy=[P(t.lon,t.lat),...top.map(r=>P(r.c.lon,r.c.lat))];
    let x0=Math.min(...xy.map(p=>p[0])), x1=Math.max(...xy.map(p=>p[0])), y0=Math.min(...xy.map(p=>p[1])), y1=Math.max(...xy.map(p=>p[1]));
    let w=Math.max(x1-x0,60)*1.6, hh=Math.max(y1-y0,60)*1.6;
    if (w/hh < VBW/VBH) w=hh*VBW/VBH; else hh=w*VBH/VBW;
    w=Math.min(w,VBW); hh=Math.min(hh,VBH);
    vb=[(x0+x1)/2-w/2,(y0+y1)/2-hh/2,w,hh];
  }
  svg.setAttribute('viewBox', vb.map(n=>n.toFixed(1)).join(' '));
  const z = vb[2]/VBW;   // keep markers the same on-screen size when zoomed
  // drawn twice: outlined shapes first, then plain fills on top. The fills hide the county
  // borders inside Ireland, so only the coastline and border edge keep their line.
  let h=`<path d="${irlPath()}" fill="var(--land)" stroke="#9fb3a6" stroke-width="${2.4*z}" stroke-linejoin="round"/>
         <path d="${irlPath()}" fill="var(--land)" stroke="var(--land)" stroke-width="${.8*z}" stroke-linejoin="round"/>`;
  COURSES.forEach((c,ci)=>{
    if (topIds.has(ci)) return;
    const [x,y]=P(c.lon,c.lat);
    const on = s==='results' ? pass.has(ci) : matches(ci);
    h+=`<circle class="pt" data-ci="${ci}" cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${(on?4:3)*z}" fill="${COL[c.type]}" opacity="${on?.85:.15}" stroke="#fff" stroke-width="${.8*z}"/>`;
  });
  const [tx,ty]=P(t.lon,t.lat);
  // put the town name on the side away from the results so the pins don't cover it
  const mx = top.length ? top.reduce((s,r)=>s+P(r.c.lon,r.c.lat)[0],0)/top.length : tx+1;
  const my = top.length ? top.reduce((s,r)=>s+P(r.c.lon,r.c.lat)[1],0)/top.length : ty+1;
  const lblDir = mx>=tx ? -1 : 1, lblUp = my>=ty;
  if (showTown) h+=`<circle cx="${tx}" cy="${ty}" r="${8*z}" fill="#c9932e" stroke="#fff" stroke-width="${3*z}"/>
      <text x="${tx+lblDir*12*z}" y="${ty+(lblUp?-10:20)*z}" text-anchor="${lblDir>0?'start':'end'}" font-size="${14*z}" font-weight="600" fill="#14251c" font-family="Inter" paint-order="stroke" stroke="#fff" stroke-width="${4*z}">${esc(t.name)}</text>`;
  top.slice().reverse().forEach((r,ri)=>{
    const i=top.length-1-ri, [x,y]=P(r.c.lon,r.c.lat), on=i===active;
    h+=`<line x1="${tx}" y1="${ty}" x2="${x}" y2="${y}" stroke="${on?'#1f5d3c':'#7a8e82'}" stroke-width="${(on?2.5:1.5)*z}" stroke-dasharray="${on?'':`${5*z} ${4*z}`}"/>`;
    h+=`<g class="pt" data-ci="${r.ci}"><circle cx="${x}" cy="${y}" r="${(on?15:12)*z}" fill="${i===0?'#1f5d3c':'#7a8e82'}" stroke="${on?'#c9932e':'#fff'}" stroke-width="${(on?3:2)*z}"/>
      <text x="${x}" y="${y+4.5*z}" text-anchor="middle" font-size="${13*z}" font-weight="700" fill="#fff" font-family="Inter">${i+1}</text></g>`;
  });

  svg.innerHTML=h;
  svg.querySelectorAll('.pt').forEach(el=>{ el.style.cursor='pointer';
    el.onmousemove=e=>showTip(e,+el.dataset.ci); el.onmouseleave=()=>$('#tip').style.display='none'; });
}
function showTip(e,ci){
  const c=COURSES[ci], tip=$('#tip'), r=$('#mapwrap').getBoundingClientRect();
  const tt = A.mode ? travel(TIDX[A.town],ci,A.mode) : null;
  tip.innerHTML=`<b>${esc(c.name)}</b><br>${cap(c.type)}${c.top100?' · Top 100':''} · ${A.mode&&STEPS[step]!=='mode'?(tt==null?'no route':fmt(tt)):esc(c.county)}`;
  tip.style.left=(e.clientX-r.left)+'px'; tip.style.top=(e.clientY-r.top)+'px'; tip.style.display='block';
}
render();
